 * subnormal is normalised, so that the hidden bit (bit 23) is set and the
 * exponent may go to 0 or below. a is finite and not zero. */
static inline void unpack_norm(u32 a, s32 *e, u32 *m)
{
    *e = (s32)((a >> 23) & 0xFFu);
    *m = a & MANT_MASK;
    if (*e) {
