{
    u32 a = to_u(fa), m;
    s32 e;

    if (is_nan(a) || (a & SIGN))
        return 0;
    e = (s32)((a >> 23) & 0xFFu) - 127;
    if (e < 0)
        return 0;
    if (e >= 32)
