hdr() { printf '/*\n * SPDX-License-Identifier: MIT\n * SPDX-FileCopyrightText: 2026 japes98\n *\n%s\n */\n\n' "$1"; }
{ hdr " * <algorithm> for the Plaits demo: only the templates Plaits uses (min, max,
 * swap, fill, copy, sort), so it builds without a C++ library. Ours, from
 * the C++ standard's descriptions (docs/DESIGN-NOTES.md, M4b)."; cat <<'EOF'
#ifndef PLAITS_DEMO_ALGORITHM
#define PLAITS_DEMO_ALGORITHM

namespace std {

template<class T> inline const T& min(const T& a, const T& b) { return b < a ? b : a; }
template<class T> inline const T& max(const T& a, const T& b) { return a < b ? b : a; }
template<class T> inline void swap(T& a, T& b) { T t = a; a = b; b = t; }

template<class I, class T> inline void fill(I first, I last, const T& value)
{
    for (; first != last; ++first)
        *first = value;
}

template<class I, class O> inline O copy(I first, I last, O out)
{
    for (; first != last; ++first, ++out)
        *out = *first;
    return out;
}

/* Insertion sort: Plaits sorts only a handful of chord ratios, once. */
template<class I> inline void sort(I first, I last)
{
    for (I i = first; i != last; ++i)
        for (I j = i; j != first && *j < *(j - 1); --j)
            swap(*j, *(j - 1));
}

}  /* namespace std */

#endif
EOF
} > $D/include/algorithm
{ hdr " * <math.h> for the Plaits demo: the functions Plaits calls, from our own
 * runtime (runtime/softfloat.c, runtime/mathf.c). No double-precision
 * function is provided: Plaits uses none."; cat <<'EOF'
#ifndef PLAITS_DEMO_MATH_H
#define PLAITS_DEMO_MATH_H

#ifdef __cplusplus
extern "C" {
#endif
float sqrtf(float x);
float sinf(float x);
float cosf(float x);
float tanf(float x);
#ifdef __cplusplus
}
#endif

static inline float fabsf(float x) { return __builtin_fabsf(x); }

#define M_PI 3.14159265358979323846

#endif
EOF
} > $D/include/math.h
{ hdr " * <cmath> for the Plaits demo: the same as our <math.h>."; echo '#include <math.h>'; } > $D/include/cmath
{ hdr " * <stddef.h> for the Plaits demo (the target is 32-bit)."; cat <<'EOF'
#ifndef PLAITS_DEMO_STDDEF_H
#define PLAITS_DEMO_STDDEF_H

typedef unsigned int size_t;
typedef int ptrdiff_t;
#define NULL 0
#define offsetof(type, member) __builtin_offsetof(type, member)

